def pst_val(table, square, color):
    r = chess.square_rank(square)
    f = chess.square_file(square)
    if color == chess.WHITE:
        return table[(7 - r) * 8 + f]
    return table[r * 8 + f]


def evaluate(board):
    """Static eval, White perspective (positive favors White)."""
    # Terminal states
    if board.is_checkmate():
        # Side to move is mated. Huge score, handled with ply in search,
        # but give a sane value here too.
        return -100000 if board.turn == chess.WHITE else 100000
    if (board.is_stalemate() or board.is_insufficient_material()
            or board.can_claim_fifty_moves()
            or board.can_claim_threefold_repetition()):
        return 0
    if board.halfmove_clock >= 100:
        return 0

    pm = board.piece_map()
    # Endgame if no queens or low non-pawn material
    w_nonpawn = 0
    b_nonpawn = 0
    w_bishops = 0
    b_bishops = 0
    w_queen = False
    b_queen = False
    for sq, pc in pm.items():
        if pc.piece_type != chess.PAWN and pc.piece_type != chess.KING:
            if pc.color == chess.WHITE:
                w_nonpawn += VAL[pc.piece_type]
            else:
                b_nonpawn += VAL[pc.piece_type]
        if pc.piece_type == chess.BISHOP:
            if pc.color == chess.WHITE:
                w_bishops += 1
            else:
                b_bishops += 1
        if pc.piece_type == chess.QUEEN:
            if pc.color == chess.WHITE:
                w_queen = True
            else:
                b_queen = True
    endgame = (not w_queen and not b_queen) or (w_nonpawn <= 1300 and b_nonpawn <= 1300)
    king_table = T_KING_END if endgame else T_KING_MID

    score = 0
    for sq, pc in pm.items():
        if pc.piece_type == chess.KING:
            b = pst_val(king_table, sq, pc.color)
        else:
            b = VAL[pc.piece_type] + pst_val(PST[pc.piece_type], sq, pc.color)
        if pc.color == chess.WHITE:
            score += b
        else:
            score -= b

    if w_bishops >= 2:
        score += 30
    if b_bishops >= 2:
        score -= 30

    return score


class SearchTimeout(Exception):
    pass


class Searcher:
    def __init__(self, deadline):
        self.deadline = deadline
        self.nodes = 0
        self.killers = {}
        self.history = {}
        self.tt = {}

    def check_time(self):
        self.nodes += 1
        if (self.nodes & 1023) == 0 and time.monotonic() > self.deadline:
            raise SearchTimeout()

    def order(self, board, moves, tt_move=None, ply=0):
        scored = []
        kh = self.killers.get(ply)
        for m in moves:
            if tt_move is not None and m == tt_move:
                scored.append((1000000, m))
                continue
            s = 0
            if board.is_capture(m):
                vic = 0
                tgt = board.piece_at(m.to_square)
                if tgt:
                    vic = VAL.get(tgt.piece_type, 0)
                elif board.is_en_passant(m):
                    vic = VAL[chess.PAWN]
                atk = 0
                src = board.piece_at(m.from_square)
                if src:
                    atk = VAL.get(src.piece_type, 0)
                s = 10000 + 10 * vic - atk
                if m.promotion:
                    s += VAL.get(m.promotion, 0)
            elif m.promotion:
                s = 9000 + VAL.get(m.promotion, 0)
            else:
                if kh is not None and m in kh:
                    s = 5000
                else:
                    s = self.history.get((m.from_square, m.to_square, m.promotion), 0)
                # Push pawns / develop slightly up in ordering
                src = board.piece_at(m.from_square)
                if src and src.piece_type == chess.PAWN:
                    s += 50
            scored.append((s, m))
        scored.sort(key=lambda x: x[0], reverse=True)
        return [m for _, m in scored]

    def quiesce(self, board, alpha, beta, ply, qdepth):
        self.check_time()
        if board.is_stalemate() or board.is_insufficient_material():
            return 0
        if board.can_claim_fifty_moves() or board.can_claim_threefold_repetition():
            return 0
        color = 1 if board.turn == chess.WHITE else -1
        if board.is_checkmate():
            return -MATE + ply
        in_check = board.is_check()
        stand = color * evaluate(board)
        if not in_check:
            if stand >= beta:
                return beta
            if stand > alpha:
                alpha = stand
            if qdepth <= 0:
                return alpha
        if in_check:
            moves = list(board.legal_moves)
            if not moves:
                return -MATE + ply
            for m in self.order(board, moves, ply=ply):
                board.push(m)
                v = -self.quiesce(board, -beta, -alpha, ply + 1, qdepth - 1)
                board.pop()
                if v >= beta:
                    return beta
                if v > alpha:
                    alpha = v
            return alpha
        # Not in check: only captures + promotions with delta pruning
        for m in board.generate_legal_captures():
            tgt = board.piece_at(m.to_square)
            gain = VAL.get(tgt.piece_type, 0) if tgt else VAL[chess.PAWN]
            if m.promotion:
                gain += VAL.get(m.promotion, 0)
            if stand + gain + 150 < alpha:
                continue
            board.push(m)
            v = -self.quiesce(board, -beta, -alpha, ply + 1, qdepth - 1)
            board.pop()
            if v >= beta:
                return beta
            if v > alpha:
                alpha = v
        # Quiet promotions can be decisive (and cheap to add)
        for m in board.generate_legal_moves():
            if m.promotion and not board.is_capture(m):
                board.push(m)
                v = -self.quiesce(board, -beta, -alpha, ply + 1, qdepth - 1)
                board.pop()
                if v >= beta:
                    return beta
                if v > alpha:
                    alpha = v
        return alpha

    def negamax(self, board, depth, alpha, beta, ply):
        self.check_time()
        if board.is_checkmate():
            return -MATE + ply
        if (board.is_stalemate() or board.is_insufficient_material()
                or board.can_claim_fifty_moves()
                or board.can_claim_threefold_repetition()):
            return 0
        if board.halfmove_clock >= 100:
            return 0
        if depth <= 0:
            return self.quiesce(board, alpha, beta, ply, 6)

        key = (board.transposition_key(), depth)
        tt_move = self.tt.get(key)
        moves = list(board.legal_moves)
        if not moves:
            if board.is_check():
                return -MATE + ply
            return 0
        ordered = self.order(board, moves, tt_move, ply)
        best = -INF
        best_move = ordered[0]
        for m in ordered:
            board.push(m)
            v = -self.negamax(board, depth - 1, -beta, -alpha, ply + 1)
            board.pop()
            if v > best:
                best = v
                best_move = m
            if v > alpha:
                alpha = v
            if alpha >= beta:
                # Killer + history update
                if not board.is_capture(m) and not m.promotion:
                    kh = self.killers.setdefault(ply, [])
                    if m not in kh:
                        kh.append(m)
                        if len(kh) > 2:
                            kh.pop(0)
                    hk = (m.from_square, m.to_square, m.promotion)
                    self.history[hk] = self.history.get(hk, 0) + depth * depth
                break
        self.tt[key] = best_move
        return best

    def search_root(self, board, max_depth):
        moves = list(board.legal_moves)
        if not moves:
            return None, 0
        # Fast path: single legal move
        if len(moves) == 1:
            return moves[0], 0
        ordered = self.order(board, moves, ply=0)
        # Fast path: immediate mate in one
        for m in ordered:
            board.push(m)
            mate = board.is_checkmate()
            board.pop()
            if mate:
                return m, MATE
        best_move = ordered[0]
        for depth in range(1, max_depth + 1):
            try:
                alpha = -INF
                beta = INF
                local_best = best_move
                local_best_score = -INF
                # Search previously-best first
                cur = ([best_move] + [m for m in ordered if m != best_move]
                       if best_move in ordered else list(ordered))
                for m in cur:
                    board.push(m)
                    v = -self.negamax(board, depth - 1, -beta, -alpha, 1)
                    board.pop()
                    if v > local_best_score:
                        local_best_score = v
                        local_best = m
                    if v > alpha:
                        alpha = v
                best_move = local_best
                # Reorder for next iteration
                ordered = ([best_move] + [m for m in cur if m != best_move])
                if local_best_score >= MATE - 50:
                    break
            except SearchTimeout:
                break
            if time.monotonic() > self.deadline:
                break
        return best_move, 0


